var original = UnityEngine.Resources.Load<GronnyAudioCatalogue>("GronnyAudio/Tutorial");
var copy = UnityEngine.Object.Instantiate(original);
try {
 foreach (var cue in copy.cues) { cue.instruction = cue.instructionDetail = ""; }
 typeof(GronnyAudioSetup).GetMethod("ApplyInstructionCaptions", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static).Invoke(null, new object[] { copy });
 foreach (var cue in copy.cues) {
  var expected = original.Find(cue.id);
  if (cue.instruction != expected.instruction || cue.instructionDetail != expected.instructionDetail) throw new System.Exception("Caption mismatch: " + cue.id);
  for (int i=0;i<cue.steps.Length;i++) if (cue.steps[i].at != expected.steps[i].at || cue.steps[i].practiceOnly != expected.steps[i].practiceOnly) throw new System.Exception("Timing mismatch: " + cue.id);
 }
 return new { cues = copy.cues.Length, captionsAndTimingsRecreated = true, originalAssetModified = false };
} finally { UnityEngine.Object.DestroyImmediate(copy); }
